"""Append C218 (idempotent): the closing measurement -- what the private half actually said."""
import io, os

p = r'D:\kaggle\rsna-knee\state\FACTS.md'
ADD = """| C218 | 🏁📊 **【收盘的真相:私榜 0.942,不是 0.958 —— 而且两半的相关性是 0.991,偏移是常数 +0.0160】** 截止后用 `competitions submissions --csv` 的 **`privateScore` 列**读到全部 50 次提交的两半分数（`work/private_scores.py`、`work/public_vs_private.py`）。<br>**① 我们的私榜分**：**tick① `57250245` = 公榜 0.958 → 私榜 `0.942`**;tick② `57478661` = 0.950 → 0.935。⇒ **最终团队分 = 0.942。**<br>**② ⚠️ 我先前的"平票抽签"解释是错的,撤回**：我以为掉到 1000+ 是 1638 队同分档内的第 4 位小数重排。**错** —— 是真的掉了 **0.016**,不是掷骰子。<br>**③ 关键测量（50 次提交）**：<br>· **公榜 − 私榜 = +0.0160，sd 仅 0.0009**（+0.014 ~ +0.018）⇒ **每一个模型都是同样的偏移** ⇒ 这是**切分的性质**（公榜那一半更容易）,不是某个模型的缺陷;<br>· **Pearson r = 0.991、Spearman r = 0.934** ⇒ **公榜排序确实预测了私榜排序**;我们公榜最好的也是私榜最好的;<br>· 我们自己的分数跨度两半都是 **0.018** ⇒ 公榜**有信息**,只是带一个常数偏移。<br>**④ ⇒ 过拟合还是欠拟合？（实测，不是叙事）**：**检测不到公榜过拟合** —— 若是拟合,越晚的提交偏移应越大;实际**最早的 0.94 时代与最后的 0.958 前沿偏移完全相同（sd 0.0009）**。**是欠拟合,但不是"模型容量"层面,而是"我们从未训练自己的模型"层面**：复现公开产物的天花板 = 私榜 0.942,而铜线（前 10% ≈ 642/6425）需要 > 0.942。<br>**⑤ ✅ 一个能量化的小发现（真正的过拟合,但很小）**：tick①（作者给的逐 finding 权重）公榜 0.958 / 私榜 **0.942**;而**平权重孪生体**（`57333305`）公榜 0.957 / 私榜 **0.942** ⇒ **那组权重公榜 +0.001、私榜 +0.000。** ⇒ **C195 里我怀疑但无法验证的事,现在验证了:它是公榜半集上的拟合,没有泛化。**<br>**⑥ ⇒ 这次输在哪,一句话**：**不是输在一千分之一,是输在"公开面的天花板本身就在铜线以下"** —— 1638 队共享公榜 0.958,而他们的私榜分数铺开在整个区间;**公榜在那个区间里不给任何分辨力**,我们复现的"公开最优"私榜价值只有 0.942。**唯一能改变结果的是训练自己的模型。** | 2026-10-23 |
"""
txt = io.open(p, encoding='utf-8').read()
if '| C218 |' in txt:
    raise SystemExit('REFUSING: C218 already present')
with io.open(p, 'a', encoding='utf-8') as fh:
    fh.write(ADD)
print('appended C218; file now', os.path.getsize(p), 'bytes')
